SourceCode.Declaration:
/// <summary>
/// Parameters for the customer rebate run. Everything the dialog shows comes
/// from the attributes below; there is no dialog code and no UI builder.
/// </summary>
[DataContractAttribute,
 SysOperationGroupAttribute('Selection', "@SYS101239", '1')]
public class ConDemoRebateContract implements SysOperationInitializable
{
    private CustGroupId custGroup;
    private NoYes       includeBlocked;
    private RecId       callerRecId;

}

Method.Source:
/// <summary>
/// Fills the defaults before the dialog is shown.
/// </summary>
public void initialize()
{
    includeBlocked = NoYes::No;
}

/// <summary>
/// Gets or sets the cust group value.
/// </summary>
/// <param name="_custGroup">The cust group (CustGroupId).</param>
/// <returns>The CustGroupId result.</returns>
public CustGroupId parmCustGroup(CustGroupId _custGroup = custGroup)
{
    custGroup = _custGroup;

    return custGroup;
}

/// <summary>
/// Gets or sets the include blocked value.
/// </summary>
/// <param name="_includeBlocked">The include blocked (NoYes).</param>
/// <returns>The NoYes result.</returns>
public NoYes parmIncludeBlocked(NoYes _includeBlocked = includeBlocked)
{
    includeBlocked = _includeBlocked;

    return includeBlocked;
}

/// <summary>
/// Gets or sets the caller rec id value.
/// </summary>
/// <param name="_callerRecId">The caller rec id (RecId).</param>
/// <returns>The RecId result.</returns>
public RecId parmCallerRecId(RecId _callerRecId = callerRecId)
{
    callerRecId = _callerRecId;

    return callerRecId;
}

/// <summary>
/// Refuses a run without a customer group.
/// </summary>
/// <returns>true when the parameters are usable; otherwise false.</returns>
/// <remarks>
/// Returning false here keeps the dialog open. checkFailed writes the
/// reason to the infolog and returns false itself.
/// </remarks>
public boolean validate()
{
    boolean ret = true;

    if (!custGroup)
    {
        ret = checkFailed(strFmt("@SYS110217", "@SYS11904"));
    }

    return ret;
}
